SELECT p.gender, p.age, p.dod, i.icustay_id, i.intime, i.outtime, i.los, p.dod AS mortality_rate, COUNT(pr.procedure_id) AS procedure_count, percent_rank() OVER (ORDER BY COUNT(pr.procedure_id)) AS procedure_rank, percent_rank() OVER (ORDER BY i.los) AS los_rank, percent_rank() OVER (ORDER BY p.dod) AS mortality_rank FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.hadm_id = i.stay_id JOIN procedures_icd pr ON pr.hadm_id = i.stay_id AND pr.chartdate BETWEEN i.intime AND i.outtime WHERE p.gender = 'F' AND p.age BETWEEN 44 AND 54 AND i.intime BETWEEN a.admittime AND a.dischtime - interval '72 hours' AND pr.icd_code = '423239' GROUP BY p.gender, p.age, p.dod, i.icustay_id, i.intime, i.outtime, i.los, p.dod ORDER BY procedure_rank, los_rank, mortality_rank;